    function statusMeta(choice) {
        if (!choice) return { cls: 'background:#fef3c7;color:#92400e;border:1px solid #fcd34d;', text: '🧪 مقترح للمعاينة — غير معتمد بعد' };
        var map = {
            option_a: { cls: 'background:#dcfce7;color:#166534;border:1px solid #86efac;', text: '✅ معتمد من المؤسس — الخيار أ' },
            option_b: { cls: 'background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;', text: '✅ معتمد من المؤسس — الخيار ب' },
            custom: { cls: 'background:#ede9fe;color:#5b21b6;border:1px solid #c4b5fd;', text: '✏️ معتمد بتعديل خاص' },
            defer: { cls: 'background:#ffedd5;color:#9a3412;border:1px solid #fdba74;', text: '⏸️ مؤجل لمزيد دراسة' },
            reject: { cls: 'background:#fee2e2;color:#991b1b;border:1px solid #fca5a5;', text: '❌ مرفوض من المؤسس' }
        };
        return map[choice] || map.option_a;
    }

    function triageBadge(tr) {
        var m = {
            founder: ['#fee2e2', '#991b1b', '🛑 قرار مؤسس جوهري'],
            split: ['#fef3c7', '#92400e', '⚖️ بتعديلات/خلاف تفصيلي'],
            consensus: ['#dcfce7', '#166534', '✅ إجماع اللجنة'],
            round2: ['#ede9fe', '#5b21b6', '🆕 مكتشفات الجولة 2']
        }[tr] || ['#f1f5f9', '#334155', tr];
        return '<span class="lab-badge" style="background:' + m[0] + ';color:' + m[1] + ';">' + m[2] + '</span>';
    }

    function filteredDecisions() {
        var q = (state.search || '').trim().toLowerCase();
        return DECISIONS.filter(function (d) {
            if (state.session !== 'all' && d.session !== state.session) return false;
            var rec = state.decisions[d.id];
            if (state.triage === 'round2' && !d.isRound2) return false;
            if (state.triage === 'undecided' && rec && rec.choice) return false;
            if (state.triage !== 'all' && state.triage !== 'round2' && state.triage !== 'undecided' && d.triage !== state.triage) return false;
            if (q) {
                var hay = (d.id + ' ' + d.title + ' ' + d.problem + ' ' + d.docRef + ' ' + d.benchmark).toLowerCase();
                if (hay.indexOf(q) === -1) return false;
            }
            return true;
        });
    }

    function updateProgressBar() {
        var done = DECISIONS.filter(function (d) { return state.decisions[d.id] && state.decisions[d.id].choice; }).length;
        var el = document.getElementById('labProgressText');
        if (el) el.textContent = 'تم حسم ' + done + ' من ' + DECISIONS.length + ' قراراً';
        var bar = document.getElementById('labProgressBarFill');
        if (bar) bar.style.width = Math.round((done / DECISIONS.length) * 100) + '%';
    }

